:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--snake);
}

.score {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text);
}

#score {
  color: var(--accent);
}

.canvas-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  overflow: hidden;
  background: var(--grid);
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  gap: 12px;
}

.overlay.hidden {
  display: none;
}

.overlay h2 {
  font-size: 1.25rem;
  color: var(--snake);
}

.overlay p {
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--muted);
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 16px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.05s;
  min-height: 48px;
}

.btn:hover:not(:disabled) {
  background: var(--accent);
  color: var(--card);
}

.btn:focus-visible {
  outline: 3px solid var(--snake);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: scale(0.97);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn.primary {
  background: var(--accent);
  color: var(--card);
}

.btn.primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 12px;
    font-size: 0.9375rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 140;

  const COLORS = {
    grid: '#0f3460',
    snake: '#4ecca3',
    head: '#6ee7b7',
    food: '#e94560'
  };

  let state = 'paused';
  let snake, dir, nextDir, food, score, timer;

  function reset() {
    snake = [{ x: 10, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * GRID),
        y: Math.floor(Math.random() * GRID)
      };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = COLORS.grid;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      ctx.fillRect(seg.x * CELL, seg.y * CELL, CELL, CELL);
    });
  }

  function tick() {
    if (state !== 'running') return;

    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function startLoop() {
    clearInterval(timer);
    timer = setInterval(tick, TICK_MS);
  }

  function gameOver() {
    state = 'over';
    clearInterval(timer);
    overlayTitle.textContent = 'Game Over';
    overlayText.innerHTML = 'Final score: <strong>' + score + '</strong>';
    overlayBtn.textContent = 'Play Again';
    overlay.classList.remove('hidden');
    pauseBtn.disabled = true;
    pauseBtn.textContent = 'Pause';
  }

  function startGame() {
    reset();
    state = 'running';
    overlay.classList.add('hidden');
    pauseBtn.disabled = false;
    pauseBtn.textContent = 'Pause';
    startLoop();
  }

  function togglePause() {
    if (state === 'running') {
      state = 'paused';
      clearInterval(timer);
      pauseBtn.textContent = 'Resume';
      overlayTitle.textContent = 'Paused';
      overlayText.textContent = 'Press Resume or the space bar to continue.';
      overlayBtn.textContent = 'Resume';
      overlay.classList.remove('hidden');
    } else if (state === 'paused') {
      state = 'running';
      pauseBtn.textContent = 'Pause';
      overlay.classList.add('hidden');
      startLoop();
    }
  }

  function restart() {
    clearInterval(timer);
    startGame();
  }

  function setDirection(x, y) {
    if (state !== 'running') return;
    if (dir.x === -x && dir.y === -y) return;
    nextDir = { x, y };
  }

  document.addEventListener('keydown', function (e) {
    const key = e.key;
    if (key === 'ArrowUp' || key === 'w' || key === 'W') {
      e.preventDefault();
      setDirection(0, -1);
    } else if (key === 'ArrowDown' || key === 's' || key === 'S') {
      e.preventDefault();
      setDirection(0, 1);
    } else if (key === 'ArrowLeft' || key === 'a' || key === 'A') {
      e.preventDefault();
      setDirection(-1, 0);
    } else if (key === 'ArrowRight' || key === 'd' || key === 'D') {
      e.preventDefault();
      setDirection(1, 0);
    } else if (key === ' ' || key === 'p' || key === 'P') {
      if (state === 'running' || state === 'paused') {
        e.preventDefault();
        togglePause();
      }
    } else if (key === 'r' || key === 'R') {
      e.preventDefault();
      restart();
    }
  });

  overlayBtn.addEventListener('click', function () {
    if (state === 'paused' && overlayBtn.textContent === 'Resume') {
      togglePause();
    } else {
      startGame();
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  reset();
})();
